launchBatt = cfg.D("LaunchBattery", 0.6);
launchH2 = cfg.D("LaunchHydrogen", 0.5);
launchInterval = Math.Max(2, cfg.D("LaunchInterval", 10));
haulerLoad = cfg.D("HaulerLoad", 250000);
maxPer = Math.Max(1, cfg.I("MaxPerCarrier", 3));
cfg.Save();
HubListen();
if (haulL != null) IGC.DisableBroadcastListener(haulL);
